const raw = $input.first().json;
const q = raw.query || raw.body || raw;
const clean = (val) => String(val || '').replace(/^=/, '').trim();

const cleanQuery = {
  execution_id: clean(q.execution_id),
  action: clean(q.action) || 'restart',
  target: clean(q.target),
  asset_type: clean(q.asset_type) || 'container',
  vmid: clean(q.vmid),
  node_ip: clean(q.node_ip) || $env.get('N8N_LOCAL_IP'),
  node_name: clean(q.node_name) || 'pve',
  pve_token: clean(q.pve_token),
  decision: clean(q.decision) || 'approve'
};

return [{ json: { query: cleanQuery } }];
